(function(root){const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function calc(p,w=[30,25,30,15]){const profit=p.price-p.cost-p.shipping-p.ad-p.price*(p.fee+p.returns)/100;const margin=profit/p.price*100;const parts=[clamp((p.growth+20)/1.2,0,100),100-p.competition,clamp(margin*2,0,100),p.supply];const sum=w.reduce((a,b)=>a+b,0);return{profit,margin,parts,score:sum?Math.round(parts.reduce((a,b,i)=>a+b*w[i],0)/sum):0}}function validate(p){const nums=['price','cost','shipping','ad','fee','returns','growth','competition','supply'];if(!p||typeof p.name!=='string'||!p.name.trim()||!['category','platform','source','date'].every(k=>typeof p[k]==='string'))throw Error('商品名称、类目、平台、来源、日期字段必须为文本');if(!nums.every(k=>typeof p[k]==='number'&&Number.isFinite(p[k])))throw Error('成本、增长率和评分字段必须为有限数字');if(p.price<=0||['cost','shipping','ad'].some(k=>p[k]<0)||['fee','returns','competition','supply'].some(k=>p[k]<0||p[k]>100)||p.growth< -100)throw Error('售价须大于0，成本非负，费率与强度为0–100，增长率不低于-100%');return p}root.Radar={calc,validate};if(typeof module!=='undefined')module.exports=root.Radar})(typeof window==='undefined'?globalThis:window);
